%[text] # Simulation with Reducer Basic model
%[text] Run simulation and plot the power loss. See the `Reducer_Basic_LoggingSetup` script for how to set up Simscape selective data logging.
model_name = "HarnessModel_Reducer";
load_system(model_name);
set_param(model_name, StopTime="100");
evalin("base", "Reducer_Basic_params")
%[text] Input signals. These are used in PS Lookup Table (1D) blocks in the model.
Reducer_setInput_AxleSide_1 %[output:66574d47]
Reducer_setInput_MotorSide_1 %[output:591a560e]
%[text] 
simOut = sim(model_name);
tt = SignalTool2.getTimetableFromLoggedSignal(simOut.logsout);
%[text] 
varnames = string(tt.Properties.VariableNames);
for idx = 1 : numel(varnames) %[output:group:2dc94617]
  SignalTool2.plotTimedData(TimedData=tt, SignalName=varnames(idx)); %[output:1c4e95b5] %[output:8d8ef4c6] %[output:04c5ff4a]
end  % for %[output:group:2dc94617]
